def solve(rows):
    n = len(rows)
    if n == 0:
        return []

    def weight_of(row):
        if isinstance(row, bool):
            # booleans are not integers for this task; treat as integer? The spec says integer row, log-string, list.
            # Booleans are not mentioned as a row type, but list fields exclude booleans.
            # If a bool appears as a row, it is not an integer row. We'll treat it as 0? But inputs follow types specified.
            return 0
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            # signed integer between pipes
            import re
            m = re.search(r'\|([+-]?\d+)\|', row)
            if m:
                return int(m.group(1))
            return 0
        if isinstance(row, list):
            total = 0
            for x in row:
                if isinstance(x, bool):
                    continue
                if isinstance(x, int):
                    total += x
                elif isinstance(x, str):
                    total += len(x)
            return total
        return 0

    state = 4
    kept = []
    for i, row in enumerate(rows):
        w = weight_of(row)
        if (state + w + i) % 7 != 4 or i == n - 1:
            kept.append(w)
        if w == 0:
            state = 4
        else:
            state = (5 * state + w) % 7

    if kept:
        shift = state % len(kept)
        if shift:
            kept = kept[shift:] + kept[:shift]

    if not kept:
        return []

    kept.sort()
    dedup = []
    for x in kept:
        if not dedup or dedup[-1] != x:
            dedup.append(x)

    sessions = []
    first = dedup[0]
    last = dedup[0]
    count = 1
    for x in dedup[1:]:
        if x - last > 8:
            sessions.append([first, last, count])
            first = x
            last = x
            count = 1
        else:
            last = x
            count += 1
    sessions.append([first, last, count])
    return sessions

def _log_weight(row):
    parts = row.split('|')
    for p in parts[1:-1]:
        s = p.strip()
        body = s[1:] if s[:1] in ('+', '-') else s
        if body.isascii() and body.isdigit():
            return int(s)
    return 0

def _weight(row):
    if isinstance(row, int):
        return int(row)
    if isinstance(row, str):
        return _log_weight(row)
    if isinstance(row, list):
        total = 0
        for f in row:
            if isinstance(f, bool):
                continue
            if isinstance(f, int):
                total += f
            elif isinstance(f, str):
                total += len(f)
        return total
    return 0

def solve(rows):
    if not rows:
        return []
    n = len(rows)
    state = 4
    kept = []
    for i, row in enumerate(rows):
        w = _weight(row)
        if (state + w + i) % 7 != 4 or i == n - 1:
            kept.append(w)
        state = 4 if w == 0 else (5 * state + w) % 7
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]
    times = sorted(set(kept))
    if not times:
        return []
    sessions = []
    first = last = times[0]
    count = 1
    for t in times[1:]:
        if t - last > 8:
            sessions.append([first, last, count])
            first = t
            count = 0
        last = t
        count += 1
    sessions.append([first, last, count])
    return sessions

