def solve(rows):
    if not rows:
        return []
    rows_list = list(rows)
    def weight_of(row):
        if isinstance(row, bool):
            return int(row)
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            m = re.search(r'\|\s*([+-]?\d+)\s*\|', row)
            if m:
                return int(m.group(1))
            parts = row.split('|')
            if len(parts) >= 3:
                try:
                    return int(parts[1].strip())
                except Exception:
                    pass
            m = re.search(r'[+-]?\d+', row)
            return int(m.group(0)) if m else 0
        if isinstance(row, (list, tuple)):
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
            return total
        return 0
    state = 4
    kept = []
    n = len(rows_list)
    for i, row in enumerate(rows_list):
        w = weight_of(row)
        if ((state + w + i) % 7 != 4) or (i == n - 1):
            kept.append(row)
        if w == 0:
            state = 4
        else:
            state = (5 * state + w) % 7
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]
    if not kept:
        return []
    uniq = sorted(set(kept))
    sessions = []
    first = prev = uniq[0]
    count = 1
    for x in uniq[1:]:
        if x - prev > 8:
            sessions.append([first, prev, count])
            first = x
            count = 1
        else:
            count += 1
        prev = x
    sessions.append([first, prev, count])
    return sessions

