import re

def solve(rows):
    n = len(rows)
    state = 4
    kept = []
    pat = re.compile(r'\|\s*([+-]?\d+)\s*\|')
    for i, r in enumerate(rows):
        if isinstance(r, bool):
            w = 0
        elif isinstance(r, int):
            w = r
        elif isinstance(r, str):
            m = pat.search(r)
            w = int(m.group(1)) if m else 0
        elif isinstance(r, (list, tuple)):
            w = 0
            for f in r:
                if isinstance(f, bool):
                    continue
                if isinstance(f, int):
                    w += f
                elif isinstance(f, str):
                    w += len(f)
        else:
            w = 0
        if (state + w + i) % 7 != 4 or i == n - 1:
            kept.append(r)
        if w == 0:
            state = 4
        else:
            state = (5 * state + w) % 7
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]
    times = sorted(set(x for x in kept if isinstance(x, int) and not isinstance(x, bool)))
    if not times:
        return []
    res = []
    start = prev = times[0]
    cnt = 1
    for t in times[1:]:
        if t - prev > 8:
            res.append([start, prev, cnt])
            start = t
            cnt = 1
        else:
            cnt += 1
        prev = t
    res.append([start, prev, cnt])
    return res

def solve(rows):
    state = 7
    kept = []
    n = len(rows)

    for idx, row in enumerate(rows):
        if type(row) is int:
            weight = row
        elif isinstance(row, str):
            parts = row.split('|')
            weight = int(parts[1])
        elif isinstance(row, list):
            weight = 0
            for item in row:
                if isinstance(item, bool):
                    continue
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)
        else:
            weight = 0

        if ((state + weight + idx) % 13 != 5) or (idx == n - 1):
            kept.append(row)

        if weight == 0:
            state = 7
        else:
            state = (3 * state + weight) % 13

    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]

    result = {}
    for row in kept:
        if not isinstance(row, str):
            continue
        key, value_str, status = row.split('|')
        if status == 'OK':
            result[key] = int(value_str)

    return [[key, result[key]] for key in sorted(result)]

def solve(rows):
    # Audit scan in original zero-based order
    state = 7
    kept_rows = []          # rows that pass the keep condition
    original_indices = []  # store original index for each kept row
    weights = []           # weight of each row (in original order)

    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: format like "|signed integer|..."
            # extract the integer between pipes
            parts = row.split('|')
            if len(parts) >= 2:
                num_str = parts[1].strip()
                try:
                    weight = int(num_str)
                except ValueError:
                    weight = 0  # fallback
            else:
                weight = 0
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of all string fields
            total = 0
            for item in row:
                if isinstance(item, bool):
                    continue
                elif isinstance(item, int):
                    total += item
                elif isinstance(item, str):
                    total += len(item)
                # ignore other types (assume only these)
            weight = total
        else:
            # unexpected type; treat as 0
            weight = 0

        weights.append(weight)

        # Keep condition: (state + weight + original_index) % 13 != 5, or if it is the last original row
        if (state + weight + idx) % 13 == 5:
            if idx == len(rows) - 1:  # last row always kept
                kept_rows.append(row)
                original_indices.append(idx)
            else:
                # omit this row
                pass
        else:
            kept_rows.append(row)
            original_indices.append(idx)

    # Update state for EVERY row (including omitted rows), in original order
    for weight in weights:
        if weight == 0:
            state = 7
        else:
            state = (3 * state + weight) % 13
    final_state = state

    # Rotate kept list LEFT by final_state modulo kept_length
    kept_length = len(kept_rows)
    if kept_length == 0:
        # empty stays empty
        pass
    else:
        shift = final_state % kept_length
        # left rotation by shift: take elements from shift to end, then 0 to shift-1
        kept_rows = kept_rows[shift:] + kept_rows[:shift]

    # Main rule: parse log rows "key|integer|status"
    # Only consider rows that are strings and match pattern: key (letters only), integer, status (OK or VOID)
    # Ignore VOID; for each key keep the LAST OK value (even if zero or negative)
    key_last_value = {}

    for row in kept_rows:
        if isinstance(row, str) and '|' in row:
            parts = row.split('|')
            if len(parts) == 3:
                key = parts[0].strip()
                status = parts[2].strip()
                if status == 'VOID':
                    continue
                if status == 'OK':
                    # parts[1] should be integer (possibly negative)
                    try:
                        val = int(parts[1].strip())
                    except ValueError:
                        # if not integer, skip? spec says integer field, so assume valid
                        continue
                    # key contains letters only? spec says keys contain letters only; we don't validate strictly
                    key_last_value[key] = val
            # other formats ignored

    # Return sorted [key, value] lists
    result = [[k, v] for k, v in key_last_value.items()]
    result.sort(key=lambda x: x[0])  # sort by key
    return result

import re

def solve(rows):
    def weight(row):
        if isinstance(row, int):
            return int(row)
        if isinstance(row, str):
            m = re.search(r'\|([+-]?\d+)\|', row)
            return int(m.group(1)) if m else 0
        if isinstance(row, list):
            total = 0
            for f in row:
                if isinstance(f, bool):
                    continue
                if isinstance(f, int):
                    total += f
                elif isinstance(f, str):
                    total += len(f)
            return total
        return 0
    n = len(rows)
    state = 7
    kept = []
    for i, row in enumerate(rows):
        w = weight(row)
        if (state + w + i) % 13 != 5 or i == n - 1:
            kept.append(row)
        state = 7 if w == 0 else (3 * state + w) % 13
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]
    last = {}
    for row in kept:
        if not isinstance(row, str):
            continue
        parts = row.split('|')
        if len(parts) != 3:
            continue
        key, val, status = parts
        if not re.fullmatch(r'[A-Za-z]+', key) or status.strip() != 'OK':
            continue
        try:
            last[key] = int(val)
        except ValueError:
            continue
    return sorted([k, v] for k, v in last.items())

