            weight = int(row.split('|')[1])
        else:
            weight = sum(field for field in row if isinstance(field, int) and not isinstance(field, bool))
            weight += sum(len(field) for field in row if isinstance(field, str))

        if (state + weight + index) % 13 != 5 or index == last:
            kept.append(row)

        state = 7 if weight == 0 else (3 * state + weight) % 13

    if kept:
        shift = state % len(kept)
        kept = kept[shift:] + kept[:shift]

    values = {}
    for row in kept:
        if isinstance(row, str):
            key, value_text, status = row.split('|')
            if status == 'OK':
                values[key] = int(value_text)

    return [[key, values[key]] for key in sorted(values)]

def solve(rows):
    n = len(rows)
    state = 7
    kept = []
    for idx, row in enumerate(rows):
        if isinstance(row, list):
            w = 0
            for f in row:
                if isinstance(f, bool):
                    continue
                elif isinstance(f, int):
                    w += f
                elif isinstance(f, str):
                    w += len(f)
        elif isinstance(row, str):
            parts = row.split('|')
            try:
                w = int(parts[1]) if len(parts) >= 2 else 0
            except Exception:
                w = 0
        elif isinstance(row, int):
            w = int(row)
        else:
            w = 0
        if (state + w + idx) % 13 != 5 or idx == n - 1:
            kept.append(row)
        if w == 0:
            state = 7
        else:
            state = (3 * state + w) % 13
    if kept:
        r = state % len(kept)
        if r:
            kept = kept[r:] + kept[:r]
    result = {}
    for row in kept:
        if not isinstance(row, str):
            continue
        parts = row.split('|')
        if len(parts) != 3:
            continue
        key, val_s, status = parts
        if not key.isalpha():
            continue
        if status != 'OK':
            continue
        try:
            val = int(val_s)
        except Exception:
            continue
        result[key] = val
    return [[k, result[k]] for k in sorted(result)]

import re

def solve(rows):
    rows = list(rows)
    n = len(rows)

    def weight(r):
        if isinstance(r, bool):
            return int(r)
        if isinstance(r, int):
            return r
        if isinstance(r, str):
            parts = r.split('|')
            if len(parts) >= 2:
                try:
                    return int(parts[1].strip())
                except ValueError:
                    return 0
            return 0
        if isinstance(r, (list, tuple)):
            w = 0
            for f in r:
                if isinstance(f, bool):
                    continue
                if isinstance(f, int):
                    w += f
                elif isinstance(f, str):
                    w += len(f)
            return w
        return 0

    state = 7
    kept = []
    for i, r in enumerate(rows):
        w = weight(r)
        if (state + w + i) % 13 != 5 or i == n - 1:
            kept.append(r)
        if w == 0:
            state = 7
        else:
            state = (3 * state + w) % 13
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]

    pat = re.compile(r'^([A-Za-z]+)\|([+-]?\d+)\|(OK|VOID)$')
    result = {}
    for r in kept:
        if not isinstance(r, str):
            continue
        m = pat.match(r.strip())
        if not m:
            continue
        key, val, status = m.group(1), int(m.group(2)), m.group(3)
        if status == 'OK':
            result[key] = val
    return [[k, result[k]] for k in sorted(result)]

