    return [[k, res[k]] for k in sorted(res)]

def solve(rows):
    def weight_of(row):
        if isinstance(row, bool):
            # booleans are not expected as rows, but treat as integer? Spec says integer row weight is that integer.
            return int(row)
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            # signed integer between pipes
            start = row.find('|')
            end = row.find('|', start + 1)
            if start == -1 or end == -1:
                raise ValueError('log-string row must contain two pipes')
            return int(row[start + 1:end].strip())
        if isinstance(row, list):
            total = 0
            for x in row:
                if isinstance(x, bool):
                    continue
                if isinstance(x, int):
                    total += x
                elif isinstance(x, str):
                    total += len(x)
            return total
        raise TypeError('unsupported row type')

    n = len(rows)
    state = 9
    kept = []
    for i, row in enumerate(rows):
        w = weight_of(row)
        if ((state + w + i) % 11 != 5) or (i == n - 1):
            kept.append(row)
        if w == 0:
            state = 9
        else:
            state = (5 * state + w) % 11

    final_state = state
    if kept:
        k = final_state % len(kept)
        kept = kept[k:] + kept[:k]

    total = 0
    for row in kept:
        price, discount = row[0], row[1]
        effective_discount = min(discount, 8)
        payable = max(price - effective_discount, 0)
        total += payable
    return total

import re


def solve(rows):
    log_pattern = re.compile(r'\|\s*([+-]?\d+)\s*\|')

    def weight_of(row):
        if isinstance(row, bool):
            return 0
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            m = log_pattern.search(row)
            return int(m.group(1)) if m else 0
        if isinstance(row, list):
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
            return total
        return 0

    n = len(rows)
    state = 9
    kept = []
    for i, row in enumerate(rows):
        w = weight_of(row)
        keep = (state + w + i) % 11 != 5 or i == n - 1
        if keep:
            kept.append(row)
        state = 9 if w == 0 else (5 * state + w) % 11

    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]

    total = 0
    for row in kept:
        price, discount = row[0], row[1]
        d = min(discount, 8)
        total += max(0, price - d)
    return total

def solve(rows):
    kept = []
    state = 9
    for i, row in enumerate(rows):
        if isinstance(row, int) and not isinstance(row, bool):
            weight = row
        elif isinstance(row, str):
            weight = int(row.split('|')[1])
        else:
            weight = sum(x for x in row if isinstance(x, int) and not isinstance(x, bool)) + sum(len(x) for x in row if isinstance(x, str))

        if (state + weight + i) % 11 != 5 or i == len(rows) - 1:
            kept.append(row)
        state = 9 if weight == 0 else (5 * state + weight) % 11

    if kept:
        shift = state % len(kept)
        kept = kept[shift:] + kept[:shift]

    total = 0
    for price, discount in kept:
        total += max(0, price - min(discount, 8))
    return total

