def solve(rows):
    def weight(row):
        if isinstance(row, bool):
            return int(row)
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            m = re.search(r'\|\s*([+-]?\d+)\s*\|', row)
            if m:
                return int(m.group(1))
            parts = row.split('|')
            if len(parts) >= 2:
                return int(parts[1].strip())
            return 0
