    import re

    def weight_of(row):
        if isinstance(row, bool):
            # Booleans are not integers for weight purposes; treat as list? But spec says integer row, log-string row, list row.
            # A bool is an int subclass, but likely not expected as a row. Treat as integer? Excluding booleans only mentioned for list fields.
            return int(row)
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            m = re.search(r'\|([+-]?\d+)\|', row)
            if m:
                return int(m.group(1))
            # fallback: signed integer between pipes, maybe multiple pipes
            parts = row.split('|')
            for p in parts:
                p = p.strip()
                if re.fullmatch(r'[+-]?\d+', p):
