            return 0
        if isinstance(row, list):
            total = 0
            for x in row:
                if isinstance(x, bool):
                    continue
                if isinstance(x, int):
                    total += x
                elif isinstance(x, str):
                    total += len(x)
            return total
        return 0

    state = 9
    kept = []
