    for i, row in enumerate(rows):
        w = weight_of(row)
        if ((state + w + i) % 11 != 1) or (i == n - 1):
            kept.append(row)
        if w == 0:
            state = 9
        else:
            state = (5 * state + w) % 11

    if kept:
        shift = state % len(kept)
        kept = kept[shift:] + kept[:shift]

    balance = 0
    result = []
    for row in kept:
        if isinstance(row, list) and len(row) >= 2:
