def solve(rows):
    def weight_of(row):
        if isinstance(row, int):
            return int(row)
        if isinstance(row, str):
            m = re.search(r'\|([+-]?\d+)\|', row)
            return int(m.group(1)) if m else 0
        if isinstance(row, list):
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
            return total
        return 0

    def as_interval(row):
        if isinstance(row, (list, tuple)) and len(row) == 2:
            s, e = row
            if isinstance(s, int) and isinstance(e, int) and not isinstance(s, bool) and not isinstance(e, bool) and s < e:
                return (s, e)
        return None

    # Audit scan in original order
    state = 5
    kept = []
    last = len(rows) - 1
    for i, row in enumerate(rows):
        w = weight_of(row)
        if (state + w + i) % 11 != 6 or i == last:
            kept.append(row)
        state = 5 if w == 0 else (5 * state + w) % 11

    # Rotate kept rows left by final state
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]

    # Main rule: merge overlapping half-open intervals (touching ones stay separate)
    intervals = sorted(iv for iv in (as_interval(r) for r in kept) if iv is not None)
    merged = []
    for s, e in intervals:
        if merged and s < merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    return merged

