    n = len(rows)
    pat = re.compile(r'\|\s*([+-]?\d+)\s*\|')

    def weight(r):
        if isinstance(r, str):
            m = pat.search(r)
            return int(m.group(1)) if m else 0
        if isinstance(r, (list, tuple)):
            w = 0
            for f in r:
                if isinstance(f, bool):
                    continue
                if isinstance(f, int):
                    w += f
                elif isinstance(f, str):
                    w += len(f)
            return w
        if isinstance(r, int):
            return int(r)
        return 0

    state = 1
    kept = []
    for i, r in enumerate(rows):
        w = weight(r)
        if (state + w + i) % 13 != 5 or i == n - 1:
            kept.append(r)
        if w == 0:
            state = 1
        else:
            state = (3 * state + w) % 13
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]

    budget = 15
    out = []
    for r in kept:
        if isinstance(r, (list, tuple)) and len(r) >= 2:
            a = min(r[0], r[1], budget)
            a = max(a, 0)
            budget -= a
            out.append(a)
    return out

def solve(rows):
    if not rows:
        return []
    n = len(rows)
    state = 4
    kept = []
    for i, row in enumerate(rows):
        if isinstance(row, bool):
            # booleans are not integers for weight purposes, but task says integer row; treat as int? 
            # The spec says integer row, log-string, list. Booleans are excluded from integer fields in list.
            # For a boolean row, it's not specified. We'll treat as integer? But to be safe, treat as int(row) if needed.
            weight = int(row)
        elif isinstance(row, int):
            weight = row
        elif isinstance(row, str):
            # log-string: signed integer between pipes
            # assume format like "...|123|..." or "|123|"
            # find between first and last pipe? "signed integer between pipes"
            # We'll extract the first occurrence of |...|
            import re
            m = re.search(r'\|([+-]?\d+)\|', row)
            if m:
                weight = int(m.group(1))
            else:
                # fallback: try to find any integer
                m2 = re.search(r'[+-]?\d+', row)
                weight = int(m2.group(0)) if m2 else 0
        elif isinstance(row, list):
            w = 0
            for x in row:
                if isinstance(x, bool):
                    continue
                if isinstance(x, int):
                    w += x
                elif isinstance(x, str):
                    w += len(x)
            weight = w
        else:
            weight = 0
        if (state + weight + i) % 7 != 5 or i == n - 1:
            kept.append(weight)
        if weight == 0:
            state = 4
        else:
            state = (3 * state + weight) % 7
    if not kept:
        return []
    k = len(kept)
    shift = state % k
    kept = kept[shift:] + kept[:shift]
    # main rule: sort and deduplicate
    times = sorted(set(kept))
    if not times:
        return []
    sessions = []
    start = times[0]
    prev = times[0]
    count = 1
    for t in times[1:]:
        if t - prev > 7:
            sessions.append([start, prev, count])
            start = t
            count = 1
        else:
            count += 1
        prev = t
    sessions.append([start, prev, count])
    return sessions

