def solve(rows):
    def row_weight(row):
        if type(row) is int:
            return row
        if isinstance(row, str):
            parts = row.split('|')
            return int(parts[1])
        if isinstance(row, list):
            total = 0
            for item in row:
                if isinstance(item, bool):
                    continue
                if isinstance(item, int):
                    total += item
                elif isinstance(item, str):
                    total += len(item)
            return total
        return 0

    state = 6
    kept = []
    n = len(rows)

    for idx, row in enumerate(rows):
        weight = row_weight(row)
        if (state + weight + idx) % 13 != 8 or idx == n - 1:
            kept.append(row)
        if weight == 0:
            state = 6
        else:
            state = (3 * state + weight) % 13

    final_state = state
    if kept:
        shift = final_state % len(kept)
        kept = kept[shift:] + kept[:shift]

    last_ok = {}
    for row in kept:
        if not isinstance(row, str):
            continue
        parts = row.split('|')
        if len(parts) != 3:
            continue
        key, value_str, status = parts
        if not key.isalpha():
            continue
        if status not in ('OK', 'VOID'):
            continue
        try:
            value = int(value_str)
        except ValueError:
            continue
        if status == 'OK':
            last_ok[key] = value

    return [[key, last_ok[key]] for key in sorted(last_ok)]

def solve(rows):
    # Audit scan in original zero-based order
    state = 6
    kept_rows = []          # rows that pass the keep condition
    weights = []            # weight of each row in original order
    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            w = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: "|signed integer|"
            # extract integer between pipes
            parts = row.split('|')
            if len(parts) == 3 and parts[0] == '' and parts[2] == '':
                # format like "|123|"
                try:
                    w = int(parts[1])
                except ValueError:
                    w = 0  # fallback
            else:
                w = 0
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of string fields
            total = 0
            for item in row:
                if isinstance(item, bool):
                    continue
                elif isinstance(item, int):
                    total += item
                elif isinstance(item, str):
                    total += len(item)
                # ignore other types (assume only these)
            w = total
        else:
            # unexpected type; treat as 0
            w = 0
        weights.append(w)
        # Keep condition: (state + weight + original_index) % 13 != 8, or if it is the last original row
        if (state + w + idx) % 13 == 8:
            if idx == len(rows) - 1:  # last row always kept
                kept_rows.append(row)
            else:
                # omit
                pass
        else:
            kept_rows.append(row)
    # Update state for EVERY row (including omitted) in original order
    for idx, row in enumerate(rows):
        w = weights[idx]
        if w == 0:
            state = 6
        else:
            state = (3 * state + w) % 13
    # final_state is the state after processing all rows
    final_state = state
    # Rotate kept list LEFT by final_state modulo kept_length
    kept_len = len(kept_rows)
    if kept_len == 0:
        rotated = []
    else:
        shift = final_state % kept_len
        rotated = kept_rows[shift:] + kept_rows[:shift]
    # Now apply main rule on rotated rows
    # Parse log rows "key|integer|status". Keys contain letters only. Status is OK or VOID.
    # Ignore VOID; for each key keep the LAST OK value (even if zero or negative)
    # Only consider rows that are strings matching the pattern? The problem says "log rows" of that format.
    # But rows may be other types (int, list, etc.) from audit; however main rule only applies to log rows.
    # We should only parse rows that are strings that match the pattern.
    # However the instruction: "Parse log rows 'key|integer|status'. Keys contain letters only. Status is OK or VOID."
    # So we iterate over rotated rows, and for each row that is a string and matches pattern, extract key and integer.
    # We'll use regex to validate: key letters only, integer (possibly negative), status OK or VOID.
    import re
    pattern = re.compile(r'^([a-zA-Z]+)\|(-?\d+)\|[OK|VOID]$')
    # But status must be exactly "OK" or "VOID", not with pipe. So pattern: ^[a-zA-Z]+\|\-?\d+\|(OK|VOID)$
    pattern = re.compile(r'^([a-zA-Z]+)\|(-?\d+)\|(OK|VOID)$')
    key_last_value = {}
    for row in rotated:
        if isinstance(row, str) and pattern.match(row):
            match = pattern.match(row)
            if match:
                key = match.group(1)
                status = match.group(3)  # group 3 is OK or VOID
                val_str = match.group(2)
                try:
                    val = int(val_str)
                except ValueError:
                    continue  # should not happen
                if status == 'OK':
                    key_last_value[key] = val
                # ignore VOID
    # Return sorted [key, value] lists
    result = [[k, v] for k, v in key_last_value.items()]
    result.sort(key=lambda x: x[0])  # sort by key
    return result

def solve(rows):
    import re

    def is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def log_parts(row):
        if isinstance(row, str):
            parts = row.split('|')
            if len(parts) == 3:
                return parts
        return None

    def weight(row):
        if is_int(row):
            return row
        if isinstance(row, str):
            parts = log_parts(row)
            return int(parts[1].strip()) if parts else 0
        if isinstance(row, list):
            total = 0
            for f in row:
                if is_int(f):
                    total += f
                elif isinstance(f, str):
                    total += len(f)
            return total
        return 0

    state = 6
    kept = []
    last = len(rows) - 1
    for idx, row in enumerate(rows):
        w = weight(row)
        if (state + w + idx) % 13 != 8 or idx == last:
            kept.append(row)
        if w == 0:
            state = 6
        else:
            state = (3 * state + w) % 13

    if kept:
        rot = state % len(kept)
        kept = kept[rot:] + kept[:rot]

    latest = {}
    for row in kept:
        parts = log_parts(row)
        if not parts:
            continue
        key, val, status = (p.strip() for p in parts)
        if not re.fullmatch('[A-Za-z]+', key):
            continue
        if status == 'OK':
            latest[key] = int(val)

    return [[k, latest[k]] for k in sorted(latest)]

