                m = re.fullmatch(r'\s*([+-]?\d+)\s*', parts[1])
                if m:
                    return int(m.group(1))
            return 0
        if isinstance(r, (list, tuple)):
            w = 0
            for f in r:
                if isinstance(f, bool):
                    continue
                if isinstance(f, int):
                    w += f
                elif isinstance(f, str):
                    w += len(f)
            return w
        return 0

    state = 6
    kept = []
