    for i, r in enumerate(rows):
        w = weight(r)
        if (state + w + i) % 13 != 8 or i == n - 1:
            kept.append(r)
        if w == 0:
            state = 6
        else:
            state = (3 * state + w) % 13
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]

    result = {}
    for r in kept:
        if not isinstance(r, str):
            continue
        parts = r.split('|')
        if len(parts) != 3:
            continue
        key, val, status = parts[0].strip(), parts[1].strip(), parts[2].strip()
        if not re.fullmatch(r'[A-Za-z]+', key):
