    def parse(s):
        parts = s.split('|')
        if len(parts) != 3:
            return None
        try:
            v = int(parts[1].strip())
        except Exception:
            return None
        return parts[0].strip(), v, parts[2].strip()

    def weight(r):
        if isinstance(r, bool):
            return 0
        if isinstance(r, int):
            return r
        if isinstance(r, str):
            p = parse(r)
            return p[1] if p else 0
        if isinstance(r, (list, tuple)):
            t = 0
            for f in r:
                if isinstance(f, bool):
                    continue
                if isinstance(f, int):
                    t += f
                elif isinstance(f, str):
                    t += len(f)
            return t
        return 0

    n = len(rows)
    state = 6
    kept = []
    for i, r in enumerate(rows):
        w = weight(r)
        if (state + w + i) % 13 != 8 or i == n - 1:
            kept.append(r)
        if w == 0:
            state = 6
        else:
            state = (3 * state + w) % 13
    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]

    res = {}
    for r in kept:
        if not isinstance(r, str):
            continue
        p = parse(r)
        if not p:
            continue
        key, v, st = p
        if st != 'OK':
            continue
        if not key.isalpha():
            continue
        res[key] = v
    return [[k, res[k]] for k in sorted(res)]

