            state = 7
        else:
            state = (5 * state + w) % 13

    if kept:
        k = state % len(kept)
        kept = kept[k:] + kept[:k]

    best = {}
    for row in kept:
        group, score, timestamp, name = row
        if group not in best:
            best[group] = row
        else:
            old = best[group]
            old_score, old_ts, old_name = old[1], old[2], old[3]
            if score > old_score:
                best[group] = row
            elif score == old_score:
                if timestamp < old_ts:
                    best[group] = row
                elif timestamp == old_ts:
                    if name > old_name:
                        best[group] = row

    result = [[g, best[g][3]] for g in sorted(best.keys())]
    return result

def solve(rows):
    # Audit scan in original zero-based order
    state = 7
    kept = []          # list of rows that pass the keep condition
    weights = []      # weight of each row in original order
    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            w = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: signed integer between pipes
            inner = row[1:-1]
            try:
                w = int(inner)
            except ValueError:
                w = 0  # fallback, though spec says signed integer between pipes
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of all string fields
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                elif isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
                # ignore other types per spec (assume only these)
            w = total
        else:
            # unexpected type; treat as 0 weight
            w = 0
        weights.append(w)
        # Keep condition: (state + weight + original_index) % 13 != 10, or if it is the last original row
        if (state + w + idx) % 13 == 10 and idx != len(rows) - 1:
            # omit this row
            pass
        else:
            kept.append(row)
    # Update state for EVERY row (including omitted) in original order
    for idx, row in enumerate(rows):
        w = weights[idx]
        if w == 0:
            state = 7
        else:
            state = (5 * state + w) % 13
    # After loop, state is the final state after processing all rows
    final_state = state
    # Rotate kept list LEFT by final_state modulo kept_length
    kept_len = len(kept)
    if kept_len == 0:
        rotated = []
    else:
        shift = final_state % kept_len
        rotated = kept[shift:] + kept[:shift]
    # Now apply main rule on rotated list
    # Rows are expected to be [group, score, timestamp, name] where:
    # group: likely string or hashable, score: int, timestamp: comparable (e.g., string or datetime), name: string
    # We'll assume timestamp is comparable (string or int) and can be compared with <
    # We need to select highest score per group, then earliest timestamp, then lexicographically greatest name
    # Build dict: group -> list of (score, timestamp, name)
    groups = {}
    for row in rotated:
        if not isinstance(row, list) or len(row) < 4:
            # skip malformed? but spec says rows follow types; assume valid
            continue
        group, score_val, timestamp, name = row
        # score should be int; timestamp should be comparable; name string
        # store as tuple (score, timestamp, name)
        if group not in groups:
            groups[group] = []
        groups[group].append((score_val, timestamp, name))
    # For each group, select best according to: highest score, then earliest timestamp, then greatest name
    best_per_group = {}
    for group, entries in groups.items():
        # sort by: score descending, timestamp ascending, name descending (lexicographically greatest)
        # use tuple key: (-score, timestamp, -name?) but name is string; we can sort with custom key
        # We'll sort entries with key: (-score, timestamp, name) but for name we want greatest lexicographically -> sort by name descending
        # So key = (-score, timestamp, name) with name reversed? No: we want highest score first, then earliest timestamp (smallest), then greatest name (largest lexicographically)
        # So sort by: score descending, timestamp ascending, name descending
        # Use sort with key that returns ( -score, timestamp, name ) but name descending requires reverse on name only; easier: sort with multiple keys
        # We'll sort entries using: key = ( -score, timestamp, name ) but name descending -> we can use name with negative? Not for string.
        # Instead sort with: key = ( -score, timestamp, name ) and then for name use reverse? No, we need consistent order.
        # Better: sort with key = ( -score, timestamp, name ) and then pick first? But name descending means among same score and timestamp, pick max name.
        # So we can sort by score descending, timestamp ascending, name descending.
        # Python sort is stable; we can sort by name descending first? No, we need multi-key.
        # Use: entries.sort(key=lambda x: (-x[0], x[1], x[2]), reverse=False) but name descending -> we need to sort name in reverse.
        # We can do: sort by score descending, then timestamp ascending, then name descending.
        # One way: sort by (-score, timestamp, name) but name ascending; then reverse name? Not directly.
        # Instead sort by (-score, timestamp, name) and then for name use a trick: use name with negative? Not possible.
        # So sort with key = (-score, timestamp, name) and then for name we want greatest -> we can sort by (-score, timestamp, -name) but -name not defined.
        # Simpler: find max by custom comparator via max with key that returns tuple where name is negated lexicographically? Not possible.
        # We'll do: for each group, find best by iterating and comparing.
        best = None
        for score_val, timestamp, name in entries:
            if best is None:
                best = (score_val, timestamp, name)
            else:
                # compare: higher score wins; if equal score, earlier timestamp wins; if equal timestamp, greater name wins
                if score_val > best[0]:
                    best = (score_val, timestamp, name)
                elif score_val == best[0]:
                    if timestamp < best[1]:
                        best = (score_val, timestamp, name)
                    elif timestamp == best[1]:
                        if name > best[2]:
                            best = (score_val, timestamp, name)
        best_per_group[group] = best[2]  # name
    # Return [group, name] sorted by group
    result = []
    for group in sorted(best_per_group.keys()):
        name = best_per_group[group]
        result.append([group, name])
    return result

