            # For a row, if it is a bool, treat as integer row? The task only mentions integer, log-string, list.
            # We'll treat bool as integer row weight (True=1, False=0) to be safe.
            return int(row)
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            m = re.search(r'\|([+-]?\d+)\|', row)
            if m:
                return int(m.group(1))
            # fallback: find any signed integer between pipes
            m = re.search(r'\|\s*([+-]?\d+)\s*\|', row)
            if m:
                return int(m.group(1))
            raise ValueError("No signed integer between pipes in log-string row: %r" % (row,))
        if isinstance(row, list):
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
            return total
        raise TypeError("Unsupported row type: %r" % (type(row),))

    state = 4
    kept = []
    n = len(rows)
    for idx, row in enumerate(rows):
        w = weight_of(row)
        if (state + w + idx) % 13 != 11 or idx == n - 1:
            kept.append(row)
        if w == 0:
            state = 4
        else:
            state = (5 * state + w) % 13

    final_state = state
    if kept:
        k = final_state % len(kept)
        kept = kept[k:] + kept[:k]

