def solve(rows):
    # Audit scan in original zero-based order
    kept_indices = []
    state = 4
    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: signed integer between pipes
            inner = row[1:-1]
            try:
                weight = int(inner)
            except ValueError:
                weight = 0  # fallback
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of all string fields
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                elif isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
                # ignore other types
            weight = total
        else:
            # unexpected type; treat as weight 0
            weight = 0

        # Keep condition: (state + weight + original_index) % 13 != 11, or if it is the last original row
        if (state + weight + idx) % 13 == 11:
            if idx == len(rows) - 1:
                kept_indices.append(idx)
            else:
                # omit
                pass
        else:
            kept_indices.append(idx)

    # Update state for EVERY row (including omitted), in original order
    state = 4
    for idx, row in enumerate(rows):
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            inner = row[1:-1]
            try:
                weight = int(inner)
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                elif isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
            weight = total
        else:
            weight = 0

        if weight == 0:
            state = 4
        else:
            state = (5 * state + weight) % 13

    # final_state is the state after processing all rows
    final_state = state

    # Build kept list in original order (only kept rows)
    kept_rows = [rows[i] for i in kept_indices]
    kept_len = len(kept_rows)
    if kept_len == 0:
        # empty stays empty
        # apply main rule on empty -> no lots
        return [0, None]

    # Rotate kept list LEFT by final_state modulo kept_length
    rotate_by = final_state % kept_len
    if rotate_by != 0:
        kept_rows = kept_rows[rotate_by:] + kept_rows[:rotate_by]

    # Main rule: Rows [expiry, quantity] describe lots.
    # Today is day 16. Include a lot only if expiry is STRICTLY later than today.
    # expiry and quantity are in the row; row format is [expiry, quantity]
    # expiry is a number (int or maybe string? assume int or comparable)
    # quantity is numeric (int or float)
    eligible_quantity = 0
    earliest_expiry = None

    for row in kept_rows:
        if not isinstance(row, list) or len(row) < 2:
            continue  # skip malformed
        expiry, quantity = row[0], row[1]
        # Ensure expiry is comparable; assume int or numeric
        # Strictly later than today (day 16)
        if expiry > 16:
            # include
            if quantity > 0:
                eligible_quantity += quantity
            # track earliest expiry among included lots
            if earliest_expiry is None or expiry < earliest_expiry:
                earliest_expiry = expiry

    # Return [quantity, expiry] with null expiry if none
    # Use None for null expiry
    return [eligible_quantity, earliest_expiry]

