        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of all string fields
            total = 0
            for field in row:
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
                # ignore booleans and other types
            weight = total
        else:
            # unexpected type; treat as 0
            weight = 0

        # Keep condition: (state + weight + original_index) % 11 != 5, or if it is the last original row
        if idx == len(rows) - 1 or (state + weight + idx) % 11 != 5:
            kept.append(row)
            original_indices.append(idx)
        # Update state for EVERY row (including omitted), after decision
        if weight == 0:
            state = 0
        else:
            state = (3 * state + weight) % 11

    # Now state has been updated for all rows (including omitted) in original order
    # final_state is the state after processing all rows
    final_state = state
    kept_len = len(kept)
    if kept_len == 0:
        # empty stays empty; no rotation
        pass
    else:
        # rotate kept list LEFT by final_state modulo kept_length
        shift = final_state % kept_len
        if shift != 0:
            kept = kept[shift:] + kept[:shift]

    # Main rule: parse log rows "key|integer|status"
    # Only consider rows that are strings and match pattern: key (letters only), integer, status (OK or VOID)
    # Ignore VOID; for each key keep the LAST OK value (even if zero or negative)
    key_last_ok = {}
    for row in kept:
        if isinstance(row, str):
            parts = row.split('|')
            if len(parts) == 3:
                key = parts[0].strip()
                status = parts[2].strip()
                if status == 'VOID':
                    continue
                if status == 'OK':
                    # parts[1] should be integer (may have sign)
                    val_str = parts[1].strip()
                    try:
                        val = int(val_str)
                        # key contains letters only? We'll assume it's valid; if not, still process
                        key_last_ok[key] = val
                    except ValueError:
                        # not an integer; ignore
                        pass
        # list rows or int rows are ignored in main rule

    # Return sorted [key, value] lists
    result = [[k, v] for k, v in key_last_ok.items()]
    result.sort(key=lambda x: x[0])  # sort by key
    return result

