        elif isinstance(row, str):
            # log-string row: signed integer between pipes
            # e.g., "|-5|" or "|12|"
            # extract the integer between pipes
            if row.startswith('|') and row.endswith('|'):
                inner = row[1:-1]
                try:
                    weight = int(inner)
                except ValueError:
                    # if not a valid integer, treat as 0? but spec says signed integer between pipes
                    # assume valid input
                    weight = 0
            else:
                # no pipes? spec says between pipes, assume valid
                weight = 0
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans plus lengths of all string fields
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                elif isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
                # ignore other types (assume only int, bool, str)
            weight = total
        else:
            # unexpected type; treat as 0
            weight = 0

        # Keep condition: (state + weight + original_index) % 7 != 2, or if it is the last original row
        if (state + weight + idx) % 7 == 2:
            if idx == len(rows) - 1:
                # last row always kept
                kept.append(row)
            else:
                # omit
                pass
        else:
            kept.append(row)

    # Update state for EVERY row (including omitted), in original order
    state = 4
    for row in rows:
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str):
            if row.startswith('|') and row.endswith('|'):
                inner = row[1:-1]
                try:
                    weight = int(inner)
                except ValueError:
                    weight = 0
            else:
                weight = 0
        elif isinstance(row, list):
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                elif isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
            weight = total
        else:
            weight = 0

        if weight == 0:
            state = 4
        else:
            state = (5 * state + weight) % 7

    # final_state is the state after processing all rows
    final_state = state

    # Rotate kept list LEFT by final_state modulo kept_length
    kept_len = len(kept)
    if kept_len == 0:
        # empty stays empty
        pass
    else:
        shift = final_state % kept_len
        # left rotate by shift: elements [shift:] + [0:shift]
        kept = kept[shift:] + kept[:shift]

    # Main rule: process kept rows that are of type [price, discount]
    # Rows that are not of that form are ignored? spec says: "Rows [price,discount] are nonnegative integer cents."
    # So only rows that are lists of two elements: price (int) and discount (int), both nonnegative?
    # Apply discount capped at 8 cents, then floor the resulting price at zero.
    total_payable = 0
    for row in kept:
        if isinstance(row, list) and len(row) == 2:
            price = row[0]
            discount = row[1]
            if isinstance(price, int) and isinstance(discount, int):
                # discount capped at 8 cents
                effective_discount = min(discount, 8)
                # resulting price = price - effective_discount, floor at zero
                resulting_price = price - effective_discount
                if resulting_price < 0:
                    resulting_price = 0
                # ensure nonnegative integer
                if isinstance(resulting_price, int):
                    total_payable += resulting_price
                else:
                    # if not int, convert? assume int
                    total_payable += int(resulting_price)
            # if price or discount not int, ignore? spec says nonnegative integer cents
        # other row types (int, str, list with other lengths) are ignored in main rule

    return total_payable

