def solve(rows):
    # Audit scan in original zero-based order
    kept = []          # list of rows that pass the keep condition
    state = 1         # start state
    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: signed integer between pipes
            inner = row[1:-1]
            try:
                weight = int(inner)
            except ValueError:
                # if not a valid integer, treat as 0? spec says signed integer between pipes
                # assume valid input
                weight = 0
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of all string fields
            total = 0
            for field in row:
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
                # ignore booleans and other types (assume only int, str, bool)
            weight = total
        else:
            # unexpected type; treat as 0
            weight = 0

        # Keep condition: (state + weight + original_index) % 11 != 10, or if it is the last original row
        if (state + weight + idx) % 11 == 10 and idx != len(rows) - 1:
            # omit this row
            pass
        else:
            kept.append(row)

        # Update state for EVERY row (including omitted), after deciding keep
        if weight == 0:
            state = 1
        else:
            state = (3 * state + weight) % 11

    # After loop, state is the final state after processing all rows
    final_state = state
    kept_len = len(kept)

    # Rotate kept list LEFT by final_state modulo kept_length; empty stays empty
    if kept_len == 0:
        rotated = []
    else:
        shift = final_state % kept_len
        rotated = kept[shift:] + kept[:shift]

    # Now apply main rule on rotated list
    # Rows are of the form [day, is_blackout] where day is int, is_blackout is bool
    eligible_days = []
    for row in rotated:
        if not isinstance(row, list) or len(row) < 2:
            continue
        day, is_blackout = row[0], row[1]
        if isinstance(day, int) and isinstance(is_blackout, bool):
            if is_blackout:
                continue  # exclude blackout rows
            if day % 4 == 0:
                continue  # exclude days divisible by 4
            eligible_days.append(day)

    # Return earliest 3 DISTINCT eligible days sorted
    # Remove duplicates while preserving order? We need distinct and earliest.
    # Sort and take first 3 unique.
    seen = set()
    unique_sorted = []
    for d in sorted(eligible_days):
        if d not in seen:
            seen.add(d)
            unique_sorted.append(d)
            if len(unique_sorted) == 3:
                break
    return unique_sorted

