def solve(rows):
    # Audit scan in original zero-based order
    kept_indices = []
    state = 4
    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: signed integer between pipes
            inner = row[1:-1]
            try:
                weight = int(inner)
            except ValueError:
                weight = 0  # fallback
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of string fields
            total = 0
            for field in row:
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
                # ignore booleans and other types
            weight = total
        else:
            # unexpected type; treat as 0 weight
            weight = 0

        # Keep row if (state + weight + idx) % 11 != 7 OR it is the last original row
        if (state + weight + idx) % 11 != 7 or idx == len(rows) - 1:
            kept_indices.append(idx)

        # Update state for EVERY row (including omitted), after decision
        if weight == 0:
            state = 4
        else:
            state = (3 * state + weight) % 11

    # Reconstruct kept rows in original order
    kept_rows = [rows[i] for i in kept_indices]

    # Final state after processing all rows
    final_state = state

    # Rotate kept list LEFT by final_state modulo kept_length
    kept_len = len(kept_rows)
    if kept_len == 0:
        rotated_rows = []
    else:
        rotate_by = final_state % kept_len
        rotated_rows = kept_rows[rotate_by:] + kept_rows[:rotate_by]

    # Now apply main rule on rotated_rows
    # Rows are either [expiry, quantity] lists (expiry and quantity), or other types (ignored for main rule)
    # Only include lots where expiry is STRICTLY later than today (day 19)
    today = 19
    total_quantity = 0
    earliest_expiry = None

    for row in rotated_rows:
        if isinstance(row, list) and len(row) == 2:
            expiry, quantity = row[0], row[1]
            # Check types: expiry should be comparable to int (e.g., int or float), quantity numeric
            try:
                expiry_val = int(expiry) if isinstance(expiry, (int, float)) else expiry
                # Only consider if expiry is strictly later than today
                if expiry_val > today:
                    # quantity should be numeric
                    if isinstance(quantity, (int, float)):
                        total_quantity += quantity
                        if earliest_expiry is None:
                            earliest_expiry = expiry_val
                        else:
                            # update earliest expiry if current is earlier
                            if expiry_val < earliest_expiry:
                                earliest_expiry = expiry_val
            except (ValueError, TypeError):
                # skip invalid expiry
                pass

    # Return [quantity, expiry] with null expiry if none
    # Use None for null expiry
    if earliest_expiry is None:
        return [total_quantity, None]
    else:
        return [total_quantity, earliest_expiry]

