def solve(rows):
    # Audit scan in original zero-based order
    state = 1
    kept = []
    weights = []
    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: signed integer between pipes
            inner = row[1:-1]
            try:
                weight = int(inner)
            except ValueError:
                weight = 0  # fallback
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of string fields
            total = 0
            for elem in row:
                if isinstance(elem, bool):
                    continue
                elif isinstance(elem, int):
                    total += elem
                elif isinstance(elem, str):
                    total += len(elem)
                # ignore other types (assume only these)
            weight = total
        else:
            # unexpected type; treat as 0 weight
            weight = 0
        weights.append(weight)
        # Keep condition: (state + weight + original_index) % 7 != 4, or if last row
        if (state + weight + idx) % 7 == 4 and idx != len(rows) - 1:
            # omit this row
            pass
        else:
            kept.append(row)
    # Update state for EVERY row (including omitted), in original order
    for idx, row in enumerate(rows):
        weight = weights[idx]
        if weight == 0:
            state = 1
        else:
            state = (5 * state + weight) % 7
    # final_state is the state after processing all rows
    final_state = state
    # Rotate kept list left by final_state modulo kept_length
    kept_len = len(kept)
    if kept_len == 0:
        rotated = []
    else:
        shift = final_state % kept_len
        rotated = kept[shift:] + kept[:shift]
    # Now apply main rule on rotated kept rows
    total_payable = 0
    for row in rotated:
        # row should be [price, discount] as per spec
        if not isinstance(row, list) or len(row) < 2:
            # skip invalid? but assume valid input
            continue
        price = row[0]
        discount = row[1]
        if not (isinstance(price, int) and price >= 0) or not (isinstance(discount, int)):
            # assume integers; if not, try convert? spec says integer cents
            # fallback: use 0 if invalid
            price = max(0, int(price)) if isinstance(price, (int, float)) else 0
            discount = int(discount) if isinstance(discount, (int, float)) else 0
        # cap discount at 6 cents
        if discount < 0:
            discount = 0
        else:
            discount = min(discount, 6)
        # floor resulting price at zero
        resulting_price = price - discount
        if resulting_price < 0:
            resulting_price = 0
        # price should be integer cents
        total_payable += int(resulting_price)
    return total_payable

