        if weight == 0:
            state = 7
        else:
            state = (3 * state + weight) % 13

    # final_state is the state after processing all rows
    final_state = state

    # Rotate kept list LEFT by final_state modulo kept_length
    kept_len = len(kept)
    if kept_len == 0:
        rotated = []
    else:
        shift = final_state % kept_len
        rotated = kept[shift:] + kept[:shift]

    # Now apply main rule:
    # Rows are nonnegative integer quantities.
    # Each order independently costs 4 cents per unit for its first 13 units and 3 thereafter.
    # Cap each order at 65 cents before adding the orders.
    # Return integer cents.
    total_cents = 0
    for row in rotated:
        if isinstance(row, int) and row >= 0:
            # quantity = row
            quantity = row
            # cost for this order:
            # first 13 units: 4 cents each
            # remaining units: 3 cents each
            if quantity <= 13:
                cost = quantity * 4
            else:
                cost = 13 * 4 + (quantity - 13) * 3
            # cap at 65 cents
            if cost > 65:
                cost = 65
            total_cents += cost
        # ignore other types (strings, lists) — they are not integer quantities

    return total_cents

