def solve(rows):
    import re

    def weight_of(row):
        if isinstance(row, bool):
            # booleans are not integers for weight purposes
            return 0
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            # signed integer between pipes
            m = re.search(r'\|\s*([+-]?\d+)\s*\|', row)
            if m:
                return int(m.group(1))
            # fallback: first signed integer in string
            m = re.search(r'[+-]?\d+', row)
            return int(m.group(0)) if m else 0
        if isinstance(row, list):
            total = 0
            for x in row:
                if isinstance(x, bool):
                    continue
                if isinstance(x, int):
                    total += x
                elif isinstance(x, str):
                    total += len(x)
            return total
        return 0

    n = len(rows)
    state = 3
    kept = []
    for i, row in enumerate(rows):
        w = weight_of(row)
        if (state + w + i) % 13 != 3 or i == n - 1:
            kept.append(row)
        if w == 0:
            state = 3
        else:
            state = (3 * state + w) % 13

    if kept:
        shift = state % len(kept)
        kept = kept[shift:] + kept[:shift]

    # Main rule: rows are [group, score, timestamp, name]
    best = {}
    for row in kept:
        if not isinstance(row, list) or len(row) < 4:
            continue
        group, score, timestamp, name = row[0], row[1], row[2], row[3]
        if group not in best:
            best[group] = (score, timestamp, name)
        else:
            bscore, btimestamp, bname = best[group]
            # highest score, then earliest timestamp, then lexicographically greatest name
            if score > bscore:
                best[group] = (score, timestamp, name)
            elif score == bscore:
                if timestamp < btimestamp:
                    best[group] = (score, timestamp, name)
                elif timestamp == btimestamp:
                    if name > bname:
                        best[group] = (score, timestamp, name)

    result = [[group, best[group][2]] for group in sorted(best.keys())]
    return result

