    if not rows:
        return []
    def weight_of(row):
        if isinstance(row, bool):
            return int(row)
        if isinstance(row, int):
            return row
        if isinstance(row, str):
            m = re.search(r'\|\s*([+-]?\d+)\s*\|', row)
            if m:
                return int(m.group(1))
            parts = row.split('|')
            for p in parts:
                p = p.strip()
                try:
                    return int(p)
                except Exception:
                    pass
            m = re.search(r'[+-]?\d+', row)
            return int(m.group(0)) if m else 0
        if isinstance(row, (list, tuple)):
            total = 0
            for field in row:
                if isinstance(field, bool):
                    continue
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
            return total
        if isinstance(row, dict):
            total = 0
            for field in row.values():
                if isinstance(field, bool):
                    continue
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
            return total
        return 0
    state = 2
    kept = []
    n = len(rows)
    for idx, row in enumerate(rows):
        w = weight_of(row)
        if ((state + w + idx) % 13 != 6) or (idx == n - 1):
            kept.append(row)
        if w == 0:
            state = 2
        else:
            state = (5 * state + w) % 13
    if kept:
        r = state % len(kept)
        if r:
            kept = kept[r:] + kept[:r]
    if not kept:
        return []
    vals = sorted(set(kept))
    sessions = []
    for t in vals:
        if not sessions or (t - sessions[-1][1] > 9):
            sessions.append([t, t, 1])
        else:
            sessions[-1][1] = t
            sessions[-1][2] += 1
    return sessions

