def solve(rows):
    # Audit scan in original zero-based order
    state = 7
    kept_rows = []          # rows that pass the keep condition
    original_indices = []  # store original index for each kept row
    weights = []           # weight of each row (in original order)

    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: format like "|signed integer|"
            # extract the integer between pipes
            inner = row[1:-1]
            try:
                weight = int(inner)
            except ValueError:
                # if not a valid integer, treat as 0? spec says signed integer between pipes
                # assume valid input
                weight = 0
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of all string fields
            total = 0
            for item in row:
                if isinstance(item, bool):
                    continue
                elif isinstance(item, int):
                    total += item
                elif isinstance(item, str):
                    total += len(item)
                # ignore other types per spec
            weight = total
        else:
            # unexpected type; treat as 0
            weight = 0

        weights.append(weight)

        # Keep condition: (state + weight + original_index) % 11 != 1, or if it is the last original row
        if idx == len(rows) - 1 or (state + weight + idx) % 11 != 1:
            kept_rows.append(row)
            original_indices.append(idx)

    # Update state for EVERY row (including omitted rows), in original order
    for weight in weights:
        if weight == 0:
            state = 7
        else:
            state = (5 * state + weight) % 11
    # After loop, state is the final state after processing all rows
    final_state = state

    # Rotate kept list LEFT by final_state modulo kept_length
    kept_length = len(kept_rows)
    if kept_length == 0:
        rotated_kept = []
    else:
        shift = final_state % kept_length
        # left rotate by shift: elements [shift:] + elements[:shift]
        rotated_kept = kept_rows[shift:] + kept_rows[:shift]

    # Now apply main rule on rotated_kept
    # Parse log rows "key|integer|status". Keys contain letters only. Status is OK or VOID.
    # Ignore VOID; for each key keep the LAST OK value, even if zero or negative.
    # Only rows that are strings matching the pattern? The spec says "log rows" of that format.
    # But after rotation, kept_rows may include ints, lists, etc. We only process string rows that match pattern.
    # We'll filter and parse only string rows that match the pattern.
    # Use regex to match key|integer|status where key letters only, integer can be negative, status OK/VOID.
    import re
    pattern = re.compile(r'^([a-zA-Z]+)\|(-?\d+)\|[A-Z]+$', re.IGNORECASE)
    # But status must be exactly "OK" or "VOID" (case-insensitive? spec says OK or VOID; assume exact case? Use case-insensitive)
    # We'll check status in {'OK', 'VOID'}

    key_last_value = {}
    for row in rotated_kept:
        if isinstance(row, str):
            # Check if it matches pattern
            m = pattern.match(row)
            if m:
                key = m.group(1)
                status = m.group(3).upper()  # normalize
                try:
                    value = int(m.group(2))
                except ValueError:
                    continue  # should not happen
                if status == 'VOID':
                    continue
                elif status == 'OK':
                    # keep last OK value
                    key_last_value[key] = value
            # else: ignore non-matching string rows

    # Return sorted [key, value] lists
    result = [[k, v] for k, v in key_last_value.items()]
    result.sort(key=lambda x: x[0])  # sort by key
    return result

