def solve(rows):
    # Audit scan in original zero-based order
    kept = []          # list of rows that pass the keep condition
    state = 2         # start state
    for idx, row in enumerate(rows):
        # Determine weight
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith('|') and row.endswith('|'):
            # log-string row: signed integer between pipes
            inner = row[1:-1]
            try:
                weight = int(inner)
            except ValueError:
                # if not a valid integer, treat as 0? spec says signed integer between pipes
                # assume valid input
                weight = 0
        elif isinstance(row, list):
            # list row: sum of integer fields excluding booleans + lengths of all string fields
            total = 0
            for field in row:
                if isinstance(field, int):
                    total += field
                elif isinstance(field, str):
                    total += len(field)
                # ignore booleans and other types (assume only int, str, bool)
            weight = total
        else:
            # unexpected type; treat as 0
            weight = 0

        # Keep condition: (state + weight + original_index) % 7 != 0, or if it is the last original row
        if (state + weight + idx) % 7 != 0 or idx == len(rows) - 1:
            kept.append(row)
        # Update state for EVERY row (including omitted), after decision
        if weight == 0:
            state = 2
        else:
            state = (5 * state + weight) % 7

    # After loop, state has been updated for all rows (last update used last row's weight)
    # Now rotate kept list left by final_state modulo kept_length
    kept_len = len(kept)
    if kept_len == 0:
        # empty stays empty
        pass
    else:
        rotate_by = state % kept_len
        # left rotation by rotate_by: elements [rotate_by:] + [0:rotate_by]
        kept = kept[rotate_by:] + kept[:rotate_by]

    # Main rule: rows are [day, is_blackout]; propose days; exclude blackout rows and days divisible by 3
    eligible_days = []
    for row in kept:
