                return int(m.group(1))
            # fallback: first and second pipe
            parts = row.split('|')
            if len(parts) >= 3:
                return int(parts[1].strip())
            return 0
        if isinstance(row, list):
            total = 0
            for x in row:
                if isinstance(x, bool):
                    continue
                if isinstance(x, int):
                    total += x
                elif isinstance(x, str):
                    total += len(x)
            return total
        return 0

    state = 10
    kept = []
