    for i, row in enumerate(rows):
        w = weight_of(row)
        if (state + w + i) % 13 != 5 or i == n - 1:
            kept.append(row)
        if w == 0:
            state = 10
        else:
            state = (5 * state + w) % 13

    if kept:
        shift = state % len(kept)
        kept = kept[shift:] + kept[:shift]

    budget = 14
    allocations = []
    for row in kept:
        capacity, request = row
        alloc = min(capacity, request, budget)
        allocations.append(alloc)
        budget -= alloc
    return allocations

